theorem condexp_le_of_ae_le {α : Type*} {m m0 : MeasurableSpace α} {μ : Measure α}
    {f g : α → ℝ}
    (hf : Integrable f μ) (hg : Integrable g μ) (h : f ≤ᵐ[μ] g) :
    (μ[f|m]) ≤ᵐ[μ] (μ[g|m])

theorem condexp_hoeffding {α : Type*} {m : MeasurableSpace α} {μ : Measure α}
    [IsFiniteMeasure μ] {D : α → ℝ} {c t : ℝ}
    (hcond : (μ[fun ω => Real.exp (t * D ω)|m]) ≤ᵐ[μ] fun _ => Real.exp (t ^ 2 * c ^ 2 / 2)) :
    (μ[fun ω => Real.exp (t * D ω)|m]) ≤ᵐ[μ]
      fun _ => Real.exp (t ^ 2 * c ^ 2 / 2)

theorem mgf_factor_measure {Ω : Type*} [MeasurableSpace Ω] {μ : Measure Ω} {ι : Type*}
    [Fintype ι] {X : ι → Ω → ℝ}
    (hindep : iIndepFun (fun _ : ι => (inferInstance : MeasurableSpace ℝ)) X μ)
    (hm : ∀ i, Measurable (X i)) (t : ℝ) :
    mgf (fun ω => ∑ i, X i ω) μ t = ∏ i, mgf (X i) μ t

theorem hoeffding_tail_independent_measure {Ω : Type*} [MeasurableSpace Ω] {μ : Measure Ω}
    [IsFiniteMeasure μ] {ι : Type*} [Fintype ι] {X : ι → Ω → ℝ}
    (hindep : iIndepFun (fun _ : ι => (inferInstance : MeasurableSpace ℝ)) X μ)
    (hm : ∀ i, Measurable (X i)) {c : ι → ℝ} {ε : ℝ}
    (hσ2 : 0 < ∑ i, c i ^ 2) (hε : 0 < ε)
    (hcoord : ∀ i, mgf (X i) μ (ε / (∑ i, c i ^ 2))
      ≤ Real.exp ((ε / (∑ i, c i ^ 2)) ^ 2 * c i ^ 2 / 2))
    (h_int : Integrable (fun ω => Real.exp ((ε / (∑ i, c i ^ 2)) * (∑ i, X i ω))) μ) :
    (μ {ω | ε ≤ ∑ i, X i ω}).toReal
      ≤ Real.exp (-(ε ^ 2) / (2 * (∑ i, c i ^ 2)))

theorem mgf_factor_sum {Ω : Type*} [MeasurableSpace Ω] {μ : Measure Ω} {ι : Type*}
    [Fintype ι] {X : ι → Ω → ℝ}
    (hindep : iIndepFun (fun _ : ι => (inferInstance : MeasurableSpace ℝ)) X μ)
    (hm : ∀ i, Measurable (X i)) (t : ℝ) :
    mgf (fun ω => ∑ i, X i ω) μ t = ∏ i, mgf (X i) μ t

theorem mgf_sum_bound_of_coord_bounds {Ω : Type*} [MeasurableSpace Ω] {μ : Measure Ω}
    {ι : Type*} [Fintype ι] {X : ι → Ω → ℝ}
    (hindep : iIndepFun (fun _ : ι => (inferInstance : MeasurableSpace ℝ)) X μ)
    (hm : ∀ i, Measurable (X i)) {c : ι → ℝ} {t : ℝ}
    (hcoord : ∀ i, mgf (X i) μ t ≤ Real.exp (t ^ 2 * c i ^ 2 / 2)) :
    mgf (fun ω => ∑ i, X i ω) μ t ≤ Real.exp (t ^ 2 * (∑ i, c i ^ 2) / 2)

theorem mixDist_iterate_sum_one {P : Matrix (Fin n) (Fin n) ℝ} {μ : Fin n → ℝ}
    (hP : rowStochastic P) (hμ : ∑ i, μ i = 1) :
    ∀ k : ℕ, ∑ j, ((mixDist P)^[k]) μ j = 1

theorem mixDist_iterate_nonneg {P : Matrix (Fin n) (Fin n) ℝ} {μ : Fin n → ℝ}
    (hP : rowStochastic P) (hμ : ∀ i, 0 ≤ μ i) :
    ∀ k : ℕ, ∀ j, 0 ≤ ((mixDist P)^[k]) μ j

theorem l1Dist_contraction {P : Matrix (Fin n) (Fin n) ℝ} {c : ℝ}
    (hrow : ∀ i, ∑ j, |P i j| ≤ c) (μ ν : Fin n → ℝ) :
    l1Dist (mixDist P μ) (mixDist P ν) ≤ c * l1Dist μ ν
